import { Worker } from 'node:worker_threads';
async function main(): Promise<void> {
  const worker = new Worker(`const { parentPort } = require('node:worker_threads'); parentPort.on('message', () => {}); parentPort.close(); setTimeout(() => { console.log('timer ran'); }, 30);`, { eval: true, stdout: false });
  const log: string[] = [];
  const code: number = await new Promise<number>((resolve) => { worker.on('exit', (c: number) => { resolve(c); }); });
  console.log('exit ' + code);
}
